using Astrea;
using NaughtyAttributes;
using UnityEngine;

namespace LittleLeo;

[CreateAssetMenu(fileName = "Character", menuName = "Data/Statistics/Character Statistics")]
public class CharacterStatistics : ScriptableObject
{
	[SerializeField]
	private bool hasCharacter;

	[SerializeField]
	[ShowIf("hasCharacter")]
	private Character character;

	[SerializeField]
	[ShowIf("hasCharacter")]
	private StatisticsData lvStatistic;

	[SerializeField]
	private StatisticsData[] allStatistics;

	[SerializeField]
	private bool orion;

	public bool HasCharacter => hasCharacter;

	public bool Orion => orion;

	public Character GetCharacter()
	{
		return character;
	}

	public StatisticsData GetLvStatistics()
	{
		return lvStatistic;
	}

	public StatisticsData[] GetAllStatistics()
	{
		return allStatistics;
	}

	public void EraseStatistics()
	{
		string characterName = "";
		if (hasCharacter)
		{
			characterName = character.CharacterName;
		}
		for (int i = 0; i < allStatistics.Length; i++)
		{
			allStatistics[i].DeleteStatisticsData(characterName);
		}
	}
}
